import overlap from 'react-big-calendar/lib/utils/layout-algorithms/overlap';
import type { fnDayLayoutAlgorithm, fnMaxIdxDFS, DayLayoutAlgorithmParams, Event } from './types';

/**
 * Depth-first search to find the maximum index value in a graph of overlapping events.
 * returns the maximum index found in the graph.
 */
const getMaxIdxDFS: fnMaxIdxDFS = (node, maxIdx, visited) => {
	let newMaxIdx = maxIdx;
	// Traverse all "friends" (overlapping events) of the current node
	for (let i = 0; i < node.friends.length; ++i) {
		// Skip already visited nodes
		if (visited.indexOf(node.friends[i]) > -1) continue;

		// Update the maximum index if the current friend's index is higher
		newMaxIdx = newMaxIdx > node.friends[i].idx ? newMaxIdx : node.friends[i].idx;

		// Mark the friend as visited
		visited.push(node.friends[i]);

		// Recursively find the maximum index in the friend's graph
		const newIdx = getMaxIdxDFS(node.friends[i], maxIdx, visited);
		newMaxIdx = newMaxIdx > newIdx ? newMaxIdx : newIdx;
	}
	return newMaxIdx;
};

/**
 * day layout algorithm to arrange events without overlap,
 * ensuring each event has a minimum width.
 * returns an array of styled events with adjusted positions and sizes.
 */
export const dayLayoutAlgorithm: fnDayLayoutAlgorithm<DayLayoutAlgorithmParams> = ({
	accessors, // Functions to access event properties, e.g., start and end times
	events, // Array of event objects
	isMobile,
	minimumStartDifference, // Minimum time difference between the start of consecutive events
	slotMetrics, // Metrics used to determine slot sizes and positions
	view, // Current view (e.g., 'day', 'week')
}) => {
	// Apply the default overlap layout algorithm to compute initial event styles
	const initialStyledEvents: Array<Event> = overlap({
		events,
		minimumStartDifference,
		slotMetrics,
		accessors,
	});

	// Sort events by vertical position (top) and height to ensure proper layering order
	initialStyledEvents.sort((eventA, eventB) => {
		const styleA = eventA.style;
		const styleB = eventB.style;

		// Compare top positions
		if (styleA.top !== styleB.top) return styleA.top > styleB.top ? 1 : -1;
		// Compare heights if top positions are equal
		else if (styleA.height !== styleB.height)
			return styleA.top + styleA.height < styleB.top + styleB.height ? 1 : -1;
		// If both top and height are equal, maintain original order
		else return 0;
	});

	// Initialize an empty list of "friends" for each event and remove unnecessary properties
	for (let i = 0; i < initialStyledEvents.length; ++i) {
		const event = initialStyledEvents[i];
		event.friends = []; // List of overlapping events
		delete event.style.left; // Remove left position style
		delete event.idx; // Remove index property
		delete event.size; // Remove size property
	}

	// Determine overlapping relationships between events
	for (let i = 0; i < initialStyledEvents.length - 1; ++i) {
		const currentEvent = initialStyledEvents[i];
		const currentTop = currentEvent.style.top; // Top position of the current event
		const currentBottom = currentEvent.style.top + currentEvent.style.height; // Bottom position of the current event

		for (let j = i + 1; j < initialStyledEvents.length; ++j) {
			const otherEvent = initialStyledEvents[j];
			const otherTop = otherEvent.style.top; // Top position of the other event
			const otherBottom = otherEvent.style.top + otherEvent.style.height; // Bottom position of the other event

			// Check if events overlap vertically
			if (
				(otherTop >= currentTop && otherBottom <= currentBottom) ||
				(otherBottom > currentTop && otherBottom <= currentBottom) ||
				(otherTop >= currentTop && otherTop < currentBottom)
			) {
				// Add each event as a "friend" (overlapping) of the other
				currentEvent.friends.push(otherEvent);
				otherEvent.friends.push(currentEvent);
			}
		}
	}

	// Assign unique index to each event to determine its horizontal position
	for (let i = 0; i < initialStyledEvents.length; ++i) {
		const event = initialStyledEvents[i];
		const availableSlots = [];

		// Initialize all slots as available (1 means available)
		for (let j = 0; j < 100; ++j) availableSlots.push(1);

		// Mark slots as reserved (0 means reserved) based on overlapping friends' indices
		for (let j = 0; j < event.friends.length; ++j) {
			if (event.friends[j].idx !== undefined) {
				availableSlots[event.friends[j].idx] = 0;
			}
		}

		// Assign the first available slot index to the event
		event.idx = availableSlots.indexOf(1);
	}

	// Define minimum width for each event and calculate sizes
	const minEventWidthPercent = view === 'day' && !isMobile ? 20 : 80; // Minimum width percentage for events
	const totalWidthPercent = 100; // Total width percentage (100%)
	const availableWidthPercent = totalWidthPercent - minEventWidthPercent; // Remaining width for distribution

	for (let i = 0; i < initialStyledEvents.length; ++i) {
		let eventSize = 0;

		// Skip events that already have a computed size
		if (initialStyledEvents[i].size) continue;

		const event = initialStyledEvents[i];
		const overlappingEvents = [];
		const maxIndex = getMaxIdxDFS(event, 0, overlappingEvents); // Find the maximum index among overlapping events
		eventSize = availableWidthPercent / (maxIndex + 1) + minEventWidthPercent; // Calculate size with minimum width and available space
		event.size = eventSize;

		// Ensure all overlapping events have the same size
		for (let j = 0; j < overlappingEvents.length; ++j) {
			overlappingEvents[j].size = eventSize;
		}
	}

	// Set final positions and dimensions for each event
	for (let i = 0; i < initialStyledEvents.length; ++i) {
		const event = initialStyledEvents[i];
		event.style.left = event.idx * event.size + ''; // Calculate horizontal position based on index and size

		// Stretch event size to maximum if possible
		let maxIndex = 0;
		for (let j = 0; j < event.friends.length; ++j) {
			const friendIndex = event.friends[j].idx;
			maxIndex = maxIndex > friendIndex ? maxIndex : friendIndex;
		}

		// Add padding between events
		const horizontalPadding = event.idx === 0 ? 0 : 3; // Padding to avoid overlap
		event.style.width = `calc(${event.size}% - ${horizontalPadding}px)`; // Set width with padding
		event.style.height = `calc(${event.style.height}% - 2px)`; // Adjust height with small adjustment
		event.style.xOffset = `calc(${event.style.left}% + ${horizontalPadding}px)`; // Set xOffset with padding
	}

	return initialStyledEvents; // Return the array of styled events with updated positions and sizes
};
