import { HStack, Text, VStack, Input, useColorMode } from '@chakra-ui/react';
import { ToolbarProps } from 'react-big-calendar';
import { RADIUS, useCalendarSettings, useIconColor } from '../../../lib';
import { ChevronLeft, ChevronRight } from '../../icons';
import { formatNavigation, ViewMenu } from '.';
import { FiltersDrawer } from './FiltersDrawer';
import { useToolbarLogic } from './useToolbarLogic';

export const MobileToolbar = ({ date, view, views, onNavigate, onView }: ToolbarProps) => {
	const {
		inputValue,
		inputType,
		handlePrevClick,
		handleNextClick,
		handleTodayClick,
		handleDateInputChange,
		createViewChangeHandler,
		viewLabels,
	} = useToolbarLogic(date, view, onNavigate, onView);

	const { settings } = useCalendarSettings();
	const { colorMode } = useColorMode();
	const iconColor = useIconColor();
	const { formattedPrev, formattedNext, todayText } = formatNavigation(date, view);
	const { calendarToolbarBackgroundColor, calendarTextColor, calendarBordersColor } = settings.styles[colorMode];
	return (
		<>
			<VStack
				className='calendar-toolbar'
				borderRadius={settings.radius.toolbar}
				backgroundColor={calendarToolbarBackgroundColor}
			>
				<HStack w='full' alignItems='center' justifyContent='space-between' px={1} py={2}>
					<HStack onClick={handlePrevClick} cursor='pointer'>
						<ChevronLeft size={18} fill={iconColor} style={{ margin: '0px' }} />
						<Text marginInline='0px !important' marginBottom='0px !important' color={calendarTextColor}>
							{formattedPrev}
						</Text>
					</HStack>
					<Text onClick={handleTodayClick} cursor='pointer'>
						{todayText}
					</Text>
					<HStack onClick={handleNextClick} cursor='pointer'>
						<Text marginInline='0px !important' marginBottom='0px !important' color={calendarTextColor}>
							{formattedNext}
						</Text>
						<ChevronRight size={18} fill={iconColor} style={{ margin: '0px' }} />
					</HStack>
				</HStack>
				<HStack w='full' marginTop={0}>
					<Input
						backgroundColor={`${calendarToolbarBackgroundColor} !important`}
						color={`${calendarTextColor} !important`}
						borderColor={`${calendarBordersColor} !important`}
						borderRadius='0px !important'
						borderBottomLeftRadius={`${RADIUS[settings.radius.toolbar]} !important`}
						placeholder='Select Date'
						size='md'
						type={inputType}
						value={inputValue}
						py='20px !important'
						onChange={handleDateInputChange}
						css={{
							'&::-webkit-calendar-picker-indicator': {
								filter: `invert(${colorMode === 'light' ? 0 : 1})`,
							},
						}}
					/>
					<FiltersDrawer />
					<ViewMenu views={views} createViewChangeHandler={createViewChangeHandler} viewLabels={viewLabels} />
				</HStack>
			</VStack>
		</>
	);
};
