import { Box, HStack, Text, Input, useColorMode } from '@chakra-ui/react';
import React, { useCallback, useState } from 'react';

import { RightArrowIcon, RoadIcon } from '../../icons';
import { useCalendarSettings } from '../../../lib';
import { IconButton } from '../../ui';

import type { IEvent } from '../../../lib';

interface IGetDirectionProps {
	event: IEvent;
}
export const GetDirection: React.FunctionComponent<IGetDirectionProps> = ({ event }) => {
	const { colorMode } = useColorMode();
	const [address, setAddress] = useState<string>('');
	const { settings } = useCalendarSettings();

	const handleAddressChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
		setAddress(event.target.value);
	}, []);

	const handleSubmit = useCallback(() => {
		const encodedStartAddress = encodeURIComponent(address);
		const encodedDestinationAddress = encodeURIComponent(event.venue);

		if (encodedDestinationAddress) {
			const url = `https://www.google.com/maps?daddr=${encodedDestinationAddress}&saddr=${
				encodedStartAddress || ''
			}`;
			window.open(url, '_blank');
		}
	}, [address, event.venue]);

	return (
		<Box p={2}>
			<HStack p='20px' borderRadius='sm' border='1px solid' borderColor='gray.200'>
				<HStack>
					<RoadIcon size={24} fill='#202124' />
					<Text lineHeight={1} fontWeight={700}>
						Get Directions
					</Text>
				</HStack>
				<Input
					_focus={{ boxShadow: 'none' }}
					sx={{
						'::placeholder': {
							color: 'gray.800',
							opacity: 1,
						},
						color: 'gray.800',
					}}
					height='45px'
					border='none'
					textAlign='center'
					placeholder='Type your address to get directions'
					onChange={handleAddressChange}
				/>
				<IconButton
					backgroundColor={settings.styles[colorMode]?.calendarButtonsColor || 'blue.500'}
					aria-label='Get event directions'
					isRound={true}
					icon={<RightArrowIcon size={24} />}
					paddingBlock='22px'
					paddingInline='12px'
					onClick={handleSubmit}
				/>
			</HStack>
		</Box>
	);
};
